// This file is automatically generated. Keep changes small and deployment-safe.
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";

const configuredUrl = import.meta.env.VITE_SUPABASE_URL?.trim();
const configuredKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY?.trim();

const blockedSupabaseHosts = new Set(["preview.supabase.co", "preview.zoot.local"]);

const isInvalidSupabaseUrl = (value?: string) => {
  if (!value) return true;
  const normalized = value.toLowerCase();
  if (normalized.includes("preview") || normalized.includes("placeholder") || normalized.includes("your-project-ref")) return true;

  try {
    return blockedSupabaseHosts.has(new URL(value).hostname);
  } catch {
    return true;
  }
};

const isInvalidSupabaseKey = (value?: string) => {
  if (!value) return true;
  const normalized = value.toLowerCase();
  return (
    normalized === "preview-anon-key" ||
    normalized === "preview-local-anon-key" ||
    normalized.includes("your-supabase") ||
    normalized.includes("your-anon-key") ||
    normalized.includes("placeholder")
  );
};

const renderConfigError = () => {
  if (typeof document === "undefined" || !document.body) return;

  document.body.replaceChildren();
  const shell = document.createElement("div");
  shell.style.fontFamily = "system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";
  shell.style.minHeight = "100vh";
  shell.style.display = "grid";
  shell.style.placeItems = "center";
  shell.style.padding = "2rem";
  shell.style.background = "#f8f5ef";
  shell.style.color = "#233024";

  const panel = document.createElement("div");
  panel.style.maxWidth = "34rem";
  panel.style.border = "1px solid rgba(35, 48, 36, 0.16)";
  panel.style.borderRadius = "1rem";
  panel.style.background = "#fffaf3";
  panel.style.padding = "1.5rem";
  panel.style.boxShadow = "0 24px 60px rgba(35, 48, 36, 0.12)";

  const heading = document.createElement("h1");
  heading.textContent = "Zoot is missing live configuration";
  heading.style.margin = "0 0 0.75rem";
  heading.style.fontSize = "1.5rem";

  const message = document.createElement("p");
  message.textContent =
    "Set real VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY values for this environment. Placeholder Supabase data is disabled.";
  message.style.margin = "0";
  message.style.lineHeight = "1.6";

  panel.append(heading, message);
  shell.append(panel);
  document.body.append(shell);
};

export const isSupabaseConfigured = Boolean(
  configuredUrl &&
    configuredKey &&
    !isInvalidSupabaseUrl(configuredUrl) &&
    !isInvalidSupabaseKey(configuredKey),
);

if (!isSupabaseConfigured) {
  renderConfigError();
  throw new Error(
    "[Zoot] Supabase public configuration is missing or contains placeholder values. Set VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY.",
  );
}

const authStorage = typeof window !== "undefined" ? window.localStorage : undefined;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";
export const supabase = createClient<Database>(configuredUrl!, configuredKey!, {
  auth: {
    storage: authStorage,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    flowType: "pkce",
  },
});
